const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scenarios=['Starting a conversation','An invitation to coffee','Receiving appreciation','Listening to a difficult day'];
const prompts=[['How welcome would you find a classmate you don’t know well starting a conversation before class?','How welcome would the average student in this class find the same interaction?'],['How pleased would you feel if a classmate you’ve spoken with a few times invited you to coffee?','How pleased would the average student in this class feel in the same situation?'],['How pleased would you feel if a classmate told you that something you said helped them?','How pleased would the average student in this class feel in the same situation?'],['How willing would you be to spend ten minutes listening to a classmate talk about an ordinary difficult day, if you had time?','How willing would the average student in this class be to do this, if they had time?']];
async function api(path,options={}){const r=await fetch('/api/live/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const b=await r.json();if(!r.ok)throw new Error(b.error||'The request failed.');return b}
function error(el,e){let n=el.querySelector('.error');if(!n){n=document.createElement('p');n.className='error note';n.setAttribute('role','alert');el.prepend(n)}n.textContent=e.message}
function chart(data,select=false,selected=[0,1,2,3]){if(!data.n)return '<div class="note">No responses yet. Open collection and share the participant link.</div>';if(data.activity==='invitation'){const labels=['Not willing to welcome or initiate','Willing to initiate; not welcome','Would welcome; hesitant to initiate','Would welcome and initiate'];return `<p><b>${data.n} responses</b> · Self-reports about hypothetical situations</p><div class="grid">${data.cells.map((n,i)=>`<div class="card"><span class="number">${n}</span><h3>${labels[i]}</h3><p>${Math.round(n/data.n*100)}% of responses</p></div>`).join('')}</div><p>Where might a welcome conversation go unstarted? There is no single expected pattern.</p>`}
return `<p><b>${data.n} responses</b> · 0–100 scale · Self-reports about hypothetical situations</p><p class="small"><span style="color:#285547">● What classmates reported</span> &nbsp; <span style="color:#93441f">◆ Estimated classmate receptiveness</span></p><div class="grid">${data.pairs.map((p,i)=>{const index=p.index??i;return `<article class="card">${select?`<label style="font-weight:normal;margin:0 0 15px"><input type="checkbox" name="result" value="${index}" ${selected.includes(index)?'checked':''}> Include in presentation</label>`:''}<h3>${scenarios[index]}</h3><div style="width:100%"><div class="meta">Reported: ${p.means[0].toFixed(1)} · Estimated: ${p.means[1].toFixed(1)}</div><div role="img" aria-label="Reported average ${p.means[0].toFixed(1)}, estimated average ${p.means[1].toFixed(1)} out of 100" style="position:relative;height:38px;border-bottom:1px solid #a5b4a9;margin:0 10px"><span style="position:absolute;left:${p.means[0]}%;top:0;transform:translateX(-50%);color:#285547;font-size:23px">●</span><span style="position:absolute;left:${p.means[1]}%;top:0;transform:translateX(-50%);color:#93441f;font-size:23px">◆</span></div><div style="display:flex;justify-content:space-between;font-size:11px"><span>0</span><span>100</span></div><details><summary style="font-size:14px">Response distributions</summary><table style="width:100%;font-size:12px;text-align:left"><caption class="small">Number of responses in each rating range</caption><thead><tr><th>Range</th><th>Reported</th><th>Estimated</th></tr></thead><tbody>${['0–19','20–39','40–59','60–79','80–100'].map((l,j)=>`<tr><td>${l}</td><td>${p.distributions[0][j]}</td><td>${p.distributions[1][j]}</td></tr>`).join('')}</tbody></table></details></div></article>`}).join('')}</div><div class="note"><b>Discuss:</b> What stands out? How might these expectations shape what people do? Accurate estimates, differences across situations, and gaps can all be useful to explore.</div>`}
let activeSession=null,poll=null;
async function home(){const app=$('#live-app');try{const me=await api('me');if(!me.signedIn){app.innerHTML='<div class="callout"><div><h3>Your sessions, kept private.</h3><p>Sign in with ChatGPT to create and manage classroom activities.</p></div><a class="button" href="/signin-with-chatgpt?return_to=%2Flive.html" target="_top">Sign in to create a session ↗</a></div><section class="section"><h2>Two ways to start a conversation.</h2><div class="grid"><article class="card tint"><h3>What does this room think?</h3><p>Four pairs of questions compare self-reported receptiveness with estimates of classmates’ receptiveness.</p></article><article class="card peach"><h3>The invisible invitation</h3><p>Explore who would welcome a conversation, and who feels willing to initiate one.</p></article></div></section>';return}const b=await api('sessions');app.innerHTML=`<div class="two-col"><form id="new-session" class="card tint"><h3>Create an activity</h3><label for="session-title">Session title</label><input id="session-title" name="title" type="text" maxlength="100" required placeholder="e.g. First-year seminar"><label for="activity-type">Choose an activity</label><select name="activity" id="activity-type"><option value="room">What does this room think?</option><option value="invitation">The invisible invitation</option></select><p class="small" style="margin-top:18px">Responses contain ratings only, without names or emails. Sessions begin with collection closed.</p><button class="button" type="submit">Create session →</button></form><div><h2 style="font-size:36px">Your sessions</h2>${b.sessions.length?b.sessions.map(s=>`<article class="resource"><div><h3>${esc(s.title)}</h3><p>${s.activity==='room'?'What does this room think?':'The invisible invitation'} · ${esc(s.status)}</p></div><button class="button secondary" data-session="${s.id}">Open →</button></article>`).join(''):'<p>No sessions yet. Create your first activity to get a participant link and QR code.</p>'}<p class="small">Only your signed-in account can manage these sessions or export their responses.</p><a class="text-link" href="/signout-with-chatgpt?return_to=%2Flive.html" target="_top">Sign out</a></div></div>`;$('#new-session').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,btn=f.querySelector('button');btn.disabled=true;try{const d=new FormData(f);const r=await api('sessions',{method:'POST',body:JSON.stringify({title:d.get('title'),activity:d.get('activity')})});location.hash=r.id;await dashboard(r.id)}catch(err){error(f,err);btn.disabled=false}});app.querySelectorAll('[data-session]').forEach(btn=>btn.onclick=()=>{location.hash=btn.dataset.session;dashboard(btn.dataset.session)})}catch(e){error(app,e)}}
async function dashboard(id){const app=$('#live-app');try{const s=await api('sessions/'+id);activeSession=id;const participant=location.origin+'/join.html?session='+s.participant,presentation=location.origin+'/present.html?session='+s.presentation;app.innerHTML=`<a class="text-link" id="back-sessions" href="live.html">← All sessions</a><section class="section" style="padding-top:30px"><span class="badge">Organizer view · ${s.status==='open'?'Collection open':'Collection closed'}${s.frozen?' · Frozen results':''}</span><h2>${esc(s.title)}</h2><div class="two-col"><div class="card tint"><h3>Invite your group</h3><label for="participant-url">Participant link</label><input id="participant-url" type="text" readonly value="${esc(participant)}"><div class="actions"><button class="button secondary" id="copy-link">Copy link</button><a class="text-link" href="${esc(participant)}" target="_blank" rel="noopener">Open survey ↗</a></div><img src="/api/live/sessions/${s.id}/qr" width="180" height="180" alt="QR code for the participant survey" style="margin:22px 0 10px"><p class="small">Share this participant link with your group. Keep the organizer view private.</p></div><div><h3>Control the activity</h3><p>Open collection before participants respond. Close it to freeze the results for discussion.</p><div class="actions"><button class="button" data-action="${s.status==='open'?'close':'open'}">${s.status==='open'?'Close & freeze results':'Open collection'}</button><a class="button secondary" href="/api/live/sessions/${s.id}/csv">Download CSV ↓</a></div><p class="small">Reopening collection keeps previous responses, clears the frozen view, and hides the presentation until you close and share again.</p><p><b>Presentation:</b> ${s.published?'Shared':'Hidden'}</p><div class="actions"><button class="button secondary" id="share-results" ${!s.frozen||s.data.n<3?'disabled':''}>Share selected results</button><button class="button secondary" data-action="hide" ${!s.published?'disabled':''}>Hide results</button></div><p class="small">At least three responses are required to share aggregate results. Sharing reveals only the selected aggregate charts.</p><a class="text-link" href="${esc(presentation)}" target="_blank" rel="noopener">Open presentation ↗</a><div class="actions"><button class="text-link" id="delete-session" style="background:none;border:0;border-bottom:1px solid;cursor:pointer;color:#8b432c">Delete session and all responses</button></div></div></div></section><section><div class="section-head"><h2>Group responses</h2><button class="button secondary" id="refresh-results">Refresh</button></div><div id="results-chart">${chart(s.data,true,s.selected)}</div><p class="small" id="updated">${s.status==='open'?'Response count updates every 10 seconds.':'These results are frozen until collection is reopened.'}</p></section>`;$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(participant);$('#copy-link').textContent='Copied'}catch{$('#participant-url').select();$('#copy-link').textContent='Select and copy the link'}};app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>mutate(s.id,{action:b.dataset.action}));$('#share-results').onclick=()=>mutate(s.id,{action:'publish',selected:s.activity==='invitation'?[0]:[...app.querySelectorAll('[name=result]:checked')].map(x=>+x.value)});$('#refresh-results').onclick=()=>dashboard(s.id);$('#delete-session').onclick=async()=>{if(!confirm('Delete this session and every response? This cannot be undone.'))return;try{await api('sessions/'+s.id,{method:'DELETE'});location.hash='';activeSession=null;clearInterval(poll);home()}catch(e){error(app,e)}};clearInterval(poll);if(s.status==='open')poll=setInterval(async()=>{try{const fresh=await api('sessions/'+s.id);if(fresh.status!=='open'){clearInterval(poll);dashboard(s.id);return}const selected=[...app.querySelectorAll('[name=result]:checked')].map(x=>+x.value);$('#results-chart').innerHTML=chart(fresh.data,true,selected);$('#updated').textContent='Last updated '+new Date().toLocaleTimeString()}catch(e){clearInterval(poll);error(app,e)}},10000)}catch(e){error(app,e)}}
async function mutate(id,b){try{await api('sessions/'+id,{method:'PATCH',body:JSON.stringify(b)});await dashboard(id)}catch(e){error($('#live-app'),e)}}
async function join(){const el=$('#join-app'),token=new URLSearchParams(location.search).get('session');if(!token){el.innerHTML='<h1>Join a session.</h1><p>Use the participant link or QR code shared by your facilitator.</p>';return}try{const s=await api('join/'+token);if(s.status!=='open'){el.innerHTML=`<h1>${esc(s.title)}</h1><div class="note">Collection is closed. Your facilitator will let you know when to participate.</div><button class="button" onclick="location.reload()">Check again</button>`;return}let submitted=false;try{submitted=localStorage.getItem('submitted-'+token)==='yes'}catch{}if(submitted){el.innerHTML='<h1>Thanks for taking part.</h1><p>Your response has been submitted. Your facilitator will lead the discussion.</p>';return}el.innerHTML=`<h1>${esc(s.title)}</h1><p>Answer about yourself, then about classmates where prompted. There are no right answers. Participation is optional.</p><p class="small">Your response contains ratings only. This activity does not ask for your name or email. Your facilitator can download individual rating responses; the presentation shows selected group summaries.</p><form id="survey">${s.activity==='room'?prompts.map((pair,i)=>`<section style="margin:35px 0"><h2 style="font-size:29px">${i+1}. ${scenarios[i]}</h2>${pair.map((p,j)=>`<label for="v${i*2+j}">${p}</label><input id="v${i*2+j}" name="v${i*2+j}" type="number" min="0" max="100" step="1" required style="width:120px;padding:10px;border:1px solid #a5b4a9"><p class="small">0 = Not at all · 100 = Extremely</p>`).join('')}</section>`).join(''):`<fieldset><legend>Would you welcome a classmate you don’t know well starting a conversation with you before class?</legend><label><input type="radio" name="v0" value="1" required> Yes</label><label><input type="radio" name="v0" value="0"> No</label></fieldset><fieldset style="margin-top:25px"><legend>Would you feel willing to start that conversation yourself?</legend><label><input type="radio" name="v1" value="1" required> Yes</label><label><input type="radio" name="v1" value="0"> No</label></fieldset>`}<div class="actions"><button class="button" type="submit">Submit response →</button></div><p class="small">Responses cannot be individually retrieved or withdrawn because they are not linked to participant accounts. Ask your facilitator about how long they will retain session data.</p></form>`;let responseId;try{responseId=sessionStorage.getItem('response-id-'+token);if(!responseId){responseId=crypto.randomUUID();sessionStorage.setItem('response-id-'+token,responseId)}}catch{responseId=crypto.randomUUID()}$('#survey').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,btn=f.querySelector('button');btn.disabled=true;try{const fd=new FormData(f),count=s.activity==='room'?8:2;await api('join/'+token,{method:'POST',body:JSON.stringify({id:responseId,values:Array.from({length:count},(_,i)=>Number(fd.get('v'+i)))})});try{localStorage.setItem('submitted-'+token,'yes')}catch{}el.innerHTML='<h1>Thanks for taking part.</h1><p>Your response was recorded. Your facilitator will lead the discussion.</p><p>You don’t need to keep this page open.</p>'}catch(err){error(f,err);btn.disabled=false}}}catch(e){error(el,e)}}
async function present(){const el=$('#present-app'),token=new URLSearchParams(location.search).get('session');if(!token){el.innerHTML='<p>Open the presentation link from your organizer dashboard.</p>';return}const render=async()=>{try{const r=await api('present/'+token);el.innerHTML=`<h2>${esc(r.title)}</h2>${r.ready?chart(r.data):`<div class="note">${esc(r.message||'Your facilitator has not shared results yet.')}</div>`}${r.ready?'<p class="small">Aggregate, frozen results. No individual responses are shown.</p>':''}` }catch(e){error(el,e)}};await render();poll=setInterval(render,10000)}
if($('#live-app')){const id=location.hash.slice(1);id?dashboard(id):home()}if($('#join-app'))join();if($('#present-app'))present();
window.addEventListener('pagehide',()=>clearInterval(poll));
